fn solve(m: i8, d: i8) -> i8 {
    // Number of days in each month for a non‐leap year
    let days_in_month = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11            => 30,
        2                          => 28,
        _                          => unreachable!("month must be in 1..=12"),
    };

    // Total cells used in the calendar grid:
    // (d-1) empty days before the 1st + days_in_month actual days
    let total_days = (d - 1) + days_in_month;

    // The number of weeks is ceil(total_days / 7).
    // Ceil(n/7) for integers can be written as (n + 6) / 7.
    (total_days + 6) / 7
}

